"use client"

import { useMemo, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { format } from 'date-fns'
import { Award, Check, Pencil, Play, Plus, Search, Trash2, X } from 'lucide-react'
import toast from 'react-hot-toast'

type AirlineEvent = {
  id: string
  title: string
  description: string
  imageUrl?: string | null
  startDate: string | Date
  endDate: string | Date
  depIcao?: string | null
  arrIcao?: string | null
  active: boolean
}

type EventFormState = {
  title: string
  description: string
  depIcao: string
  arrIcao: string
  startDate: string
  endDate: string
  imageUrl: string
}

const emptyForm: EventFormState = {
  title: '',
  description: '',
  depIcao: '',
  arrIcao: '',
  startDate: '',
  endDate: '',
  imageUrl: '',
}

function toDateInputValue(value: string | Date | null | undefined) {
  if (!value) return ''
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return ''
  return format(date, "yyyy-MM-dd'T'HH:mm")
}

function toDisplayDate(value: string | Date | null | undefined) {
  if (!value) return '∞'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return '∞'
  return format(date, 'dd/MM/yyyy')
}

function getEventType(event: AirlineEvent) {
  return event.depIcao && event.arrIcao ? 'tour' : 'announcement'
}

export default function AirlineEventList({ initialEvents, airlineId }: { initialEvents: AirlineEvent[]; airlineId: string }) {
  const queryClient = useQueryClient()

  const [search, setSearch] = useState('')
  const [showForm, setShowForm] = useState(false)
  const [editingEventId, setEditingEventId] = useState<string | null>(null)
  const [form, setForm] = useState<EventFormState>(emptyForm)

  const { data: events = initialEvents, isLoading } = useQuery<AirlineEvent[]>({
    queryKey: ['airline-events', airlineId],
    queryFn: async () => {
      const res = await fetch('/api/airline/events')
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to load events')
      return data
    },
    initialData: initialEvents,
    refetchInterval: 5000,
  })

  const saveMutation = useMutation({
    mutationFn: async (payload: Record<string, unknown>) => {
      const isEdit = Boolean(editingEventId)
      const endpoint = isEdit ? `/api/airline/events/${editingEventId}` : '/api/airline/events'
      const method = isEdit ? 'PATCH' : 'POST'

      const res = await fetch(endpoint, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to save event')
      return data
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['airline-events', airlineId] })
      toast.success(editingEventId ? 'Event updated' : 'Event created')
      setShowForm(false)
      setEditingEventId(null)
      setForm(emptyForm)
    },
    onError: (error: any) => toast.error(error.message || 'Failed to save event'),
  })

  const toggleMutation = useMutation({
    mutationFn: async (event: AirlineEvent) => {
      const res = await fetch(`/api/airline/events/${event.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ active: !event.active }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to update event status')
      return data
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['airline-events', airlineId] })
      toast.success('Event status updated')
    },
    onError: (error: any) => toast.error(error.message || 'Failed to update event status'),
  })

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/airline/events/${id}`, { method: 'DELETE' })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Failed to delete event')
      return data
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['airline-events', airlineId] })
      toast.success('Event deleted')
    },
    onError: (error: any) => toast.error(error.message || 'Failed to delete event'),
  })

  const filteredEvents = useMemo(() => {
    const q = search.trim().toLowerCase()
    if (!q) return events
    return events.filter((event) => {
      return [event.title, event.description, event.depIcao || '', event.arrIcao || '', getEventType(event)]
        .join(' ')
        .toLowerCase()
        .includes(q)
    })
  }, [events, search])

  const openCreate = () => {
    setEditingEventId(null)
    setForm(emptyForm)
    setShowForm(true)
  }

  const openEdit = (event: AirlineEvent) => {
    setEditingEventId(event.id)
    setForm({
      title: event.title,
      description: event.description,
      depIcao: event.depIcao || '',
      arrIcao: event.arrIcao || '',
      startDate: toDateInputValue(event.startDate),
      endDate: toDateInputValue(event.endDate),
      imageUrl: event.imageUrl || '',
    })
    setShowForm(true)
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    if (!form.title.trim() || !form.description.trim() || !form.startDate || !form.endDate) {
      toast.error('Title, description, start and end date are required')
      return
    }

    const payload = {
      title: form.title.trim(),
      description: form.description.trim(),
      depIcao: form.depIcao.trim().toUpperCase() || undefined,
      arrIcao: form.arrIcao.trim().toUpperCase() || undefined,
      imageUrl: form.imageUrl.trim() || undefined,
      startDate: new Date(form.startDate).toISOString(),
      endDate: new Date(form.endDate).toISOString(),
    }

    saveMutation.mutate(payload)
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
        <h1 className="section-title">Events</h1>

        <div className="flex items-center gap-2">
          <button onClick={openCreate} className="btn-secondary border-sky-500/40 text-sky-400 hover:text-sky-300">
            <Plus className="h-4 w-4" />
            CREATE EVENT
          </button>

          <div className="relative w-64">
            <Search className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search"
              className="input h-10 border-slate-700 bg-slate-950 pr-10 text-slate-100 placeholder:text-slate-500"
            />
          </div>
        </div>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="rounded-md border border-slate-700 bg-slate-900/80 p-4">
          <div className="mb-3 flex items-center justify-between">
            <h2 className="text-sm font-semibold uppercase tracking-wide text-sky-400">
              {editingEventId ? 'Edit Event' : 'Create Event'}
            </h2>
            <button
              type="button"
              onClick={() => {
                setShowForm(false)
                setEditingEventId(null)
                setForm(emptyForm)
              }}
              className="inline-flex items-center gap-1 text-xs text-slate-400 hover:text-slate-200"
            >
              <X className="h-3.5 w-3.5" /> Close
            </button>
          </div>

          <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
            <input
              className="input border-slate-700 bg-slate-950"
              placeholder="Event title"
              value={form.title}
              onChange={(e) => setForm((prev) => ({ ...prev, title: e.target.value }))}
            />
            <input
              className="input border-slate-700 bg-slate-950"
              placeholder="Image URL (optional)"
              value={form.imageUrl}
              onChange={(e) => setForm((prev) => ({ ...prev, imageUrl: e.target.value }))}
            />
            <textarea
              className="input border-slate-700 bg-slate-950 md:col-span-2"
              rows={3}
              placeholder="Description"
              value={form.description}
              onChange={(e) => setForm((prev) => ({ ...prev, description: e.target.value }))}
            />
            <input
              className="input border-slate-700 bg-slate-950"
              placeholder="Departure ICAO (optional)"
              value={form.depIcao}
              onChange={(e) => setForm((prev) => ({ ...prev, depIcao: e.target.value }))}
            />
            <input
              className="input border-slate-700 bg-slate-950"
              placeholder="Arrival ICAO (optional)"
              value={form.arrIcao}
              onChange={(e) => setForm((prev) => ({ ...prev, arrIcao: e.target.value }))}
            />
            <input
              type="datetime-local"
              className="input border-slate-700 bg-slate-950"
              value={form.startDate}
              onChange={(e) => setForm((prev) => ({ ...prev, startDate: e.target.value }))}
            />
            <input
              type="datetime-local"
              className="input border-slate-700 bg-slate-950"
              value={form.endDate}
              onChange={(e) => setForm((prev) => ({ ...prev, endDate: e.target.value }))}
            />
          </div>

          <div className="mt-3 flex justify-end">
            <button type="submit" className="btn-primary" disabled={saveMutation.isPending}>
              {saveMutation.isPending ? 'Saving...' : editingEventId ? 'Save Event' : 'Create Event'}
            </button>
          </div>
        </form>
      )}

      <div className="overflow-hidden rounded-md border border-slate-700 bg-slate-900/70">
        <div className="grid grid-cols-[2.2fr_0.8fr_0.8fr_0.8fr_0.9fr_0.9fr_0.8fr] border-b border-slate-700 px-4 py-2 text-xs font-semibold uppercase tracking-wide text-sky-400">
          <span>Event Title</span>
          <span>Type</span>
          <span>Started</span>
          <span>Closed</span>
          <span>Start Date</span>
          <span>End Date</span>
          <span className="text-right">Actions</span>
        </div>

        {isLoading && filteredEvents.length === 0 ? (
          <div className="px-4 py-6 text-sm text-slate-400">Loading events...</div>
        ) : filteredEvents.length === 0 ? (
          <div className="px-4 py-8 text-sm text-slate-400">No events found.</div>
        ) : (
          <div>
            {filteredEvents.map((event) => {
              const now = Date.now()
              const startTs = new Date(event.startDate).getTime()
              const endTs = new Date(event.endDate).getTime()
              const started = Number.isFinite(startTs) ? now >= startTs : false
              const closed = Number.isFinite(endTs) ? now > endTs || !event.active : !event.active

              return (
                <div
                  key={event.id}
                  className="grid grid-cols-[2.2fr_0.8fr_0.8fr_0.8fr_0.9fr_0.9fr_0.8fr] items-center border-b border-slate-800 px-4 py-3 text-sm text-slate-200"
                >
                  <div className="flex items-center gap-2">
                    <Award className="h-4 w-4 text-amber-400" />
                    <span className="truncate">{event.title}</span>
                  </div>
                  <span className="lowercase text-slate-400">{getEventType(event)}</span>
                  <span>{started ? <Check className="h-4 w-4 text-emerald-500" /> : <X className="h-4 w-4 text-slate-600" />}</span>
                  <span>{closed ? <Check className="h-4 w-4 text-emerald-500" /> : <X className="h-4 w-4 text-slate-600" />}</span>
                  <span className="text-slate-400">{toDisplayDate(event.startDate)}</span>
                  <span className="text-slate-400">{toDisplayDate(event.endDate)}</span>

                  <div className="flex items-center justify-end gap-2">
                    <button
                      onClick={() => toggleMutation.mutate(event)}
                      className="text-sky-500 hover:text-sky-400"
                      title={event.active ? 'Deactivate event' : 'Activate event'}
                    >
                      <Play className="h-4 w-4" />
                    </button>
                    <button
                      onClick={() => deleteMutation.mutate(event.id)}
                      className="text-red-500 hover:text-red-400"
                      title="Delete event"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                    <button onClick={() => openEdit(event)} className="text-emerald-500 hover:text-emerald-400" title="Edit event">
                      <Pencil className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}